import math

def count_divisors(n):
    """Calculates tau(n), the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates d(n), the number of positive divisors of n other than 1 and itself."""
    if n == 1:
        return 0 # Divisors of 1: {1}. Divisors other than 1 and itself: {}. Count is 0.
    tau_n = count_divisors(n)
    # For n > 1, tau_n >= 2 (divisors 1 and n always exist).
    return tau_n - 2

